import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Lumberjacking","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/lumberjacking.md","filePath":"en/guide/professions/lumberjacking.md"}'),i={name:"en/guide/professions/lumberjacking.md"};function l(s,e,n,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="lumberjacking" tabindex="-1">Lumberjacking <a class="header-anchor" href="#lumberjacking" aria-label="Permalink to &quot;Lumberjacking&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Know the trees you harvest: species, maturity, condition and useful timber.</li><li>Selection and controlled felling should reward knowledge over indiscriminate clearing.</li><li>Fallen trees could change routes; protection and recovery rules remain open.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Assess</td><td>Read species, health and approximate timber quality before cutting.</td></tr><tr><td>Choose an approach</td><td>Quick felling, controlled felling and selective cutting are possible <a href="/Syrolands-Public/en/guide/characters/techniques.html">techniques</a>.</td></tr><tr><td>Learn the region</td><td>Use a Forester’s Journal to build knowledge of trees and local ecology.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Chopping trees yields logs, which can become boards.</td><td>Tree condition and selection should improve useful yield, time and tool wear.</td></tr><tr><td>The familiar harvest loop treats trees as sources of wood.</td><td>A felled tree could occupy space and temporarily alter a chokepoint.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/lumberjacking/" target="_blank" rel="noreferrer">Lumberjacking</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A forester could select healthy timber for a bowyer while leaving poor trees alone. Controlled felling might also obstruct a route where world protections allow it.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Better selection should recover more useful wood with less wasted time or tool wear.</li><li>Regrowth, overharvesting and route-blocking limits remain undecided. Improvised bridges are only a possible later use.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/en/guide/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/en/guide/world/living-world.html">Living World</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/lumberjacking.html">Lumberjacking</a></p>',18)])])}const m=a(i,[["render",l]]);export{p as __pageData,m as default};
